def add_two_numbers(l1, l2):
    def to_int(digits):
        total = 0
        place = 1
        for d in digits:
            total += d * place
            place *= 10
        return total
    s = to_int(l1) + to_int(l2)
    if s == 0:
        return [0]
    out = []
    while s:
        out.append(s % 10)
        s //= 10
    return out

