class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def build(values):
    dummy = ListNode()
    cur = dummy
    for v in values:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next

def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def add_two_numbers(l1, l2):
    head1 = build(l1)
    head2 = build(l2)
    dummy = ListNode()
    curr = dummy
    carry = 0
    while head1 or head2 or carry:
        v1 = head1.val if head1 else 0
        v2 = head2.val if head2 else 0
        total = v1 + v2 + carry
        carry = total // 10
        curr.next = ListNode(total % 10)
        curr = curr.next
        if head1:
            head1 = head1.next
        if head2:
            head2 = head2.next
    return to_list(dummy.next)
